  String? sanitizeImageUrl(String? url) {
    if (url == null || url.trim().isEmpty) return null;

    // Already valid
    if (url.startsWith('http://') || url.startsWith('https://')) return url;

    // If backend returns domain only
    if (url.startsWith('www.') || url.contains('.')) {
      return 'https://$url';
    }

    // Otherwise invalid
    return null;
  }

  String returnPhoneNoStructure(String phoneNo) {
    if (phoneNo.substring(0, 1).contains('0')) {
      phoneNo = phoneNo.substring(1);
    }
    notifyListeners();
    return phoneNo;
  }

  String returnPhoneNoStructureAdd234After(String phoneNo) {
    if (phoneNo.startsWith('0')) {
      phoneNo = '+234${phoneNo.substring(1)}';
    } else {
      phoneNo = '+234${phoneNo.substring(0)}';
    }
    notifyListeners();
    return phoneNo;
  }

  String returnPhoneNoStructureAdd234AfterAgain(String phoneNo) {
    if (phoneNo.startsWith('+234')) {
      phoneNo = phoneNo;
    } else if (phoneNo.startsWith('0')) {
      phoneNo = '+234${phoneNo.substring(1)}';
    } else {
      phoneNo = '+234${phoneNo.substring(0)}';
    }
    notifyListeners();
    return phoneNo;
  }

  String formatPhoneNumber(String phoneNumber) {
    if (phoneNumber.startsWith('+234')) {
      return phoneNumber.replaceFirst('+234', '0');
    }
    if (!phoneNumber.startsWith('0')) {
      return '0$phoneNumber';
    }
    return phoneNumber; // return unchanged if it doesn't start with +234
  }

  String formatPhoneNumberForWelcomeScreen(String phoneNumber) {
    if (phoneNumber.startsWith('+234')) {
      return phoneNumber;
    }
    if (phoneNumber.startsWith('0')) {
      return '+234${phoneNumber.substring(1)}';
    }
    return '+234$phoneNumber'; // return unchanged if it doesn't start with +234
  }

  String returnPhoneNoStructureWith234(String phoneNo) {
    if (phoneNo.substring(4) == '0') {
      phoneNo = phoneNo.substring(4);
    } else {
      phoneNo = phoneNo;
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      notifyListeners();
    });
    return phoneNo;
  }

