  setSubscriptionModalFlow({
    AuthViewModel? model,
    BuildContext? context,
    String? planType,
    String? planTier,
    String? planId,
    String? hmoId,
    d.Plan? data,
  }) {
    if (linSubIndex == 2) {
      return secondSubModalFlow(
        model: model,
        context: context,
        planType: planType,
        planTier: planTier,
      );
    }
    if (linSubIndex == 3) {
      return thirdSubModalFlow(
        model: model,
        context: context,
        planType: planType,
        planTier: planTier,
      );
    }
    if (linSubIndex == 4) {
      return fourthSubModalFlow(
        model: model,
        context: context,
        planType: planType,
        planTier: planTier,
        planId: planId,
        data: data,
        hmoId: hmoId,
      );
    }
    if (linSubIndex == 5) {
      return fifthSubModalFlow(
        model: model,
        context: context,
        planType: planType,
        planTier: planTier,
        planId: planId,
        data: data,
        hmoId: hmoId,
      );
    }
    return firstSubModalFlow(
      model: model,
      context: context,
      planType: planType,
      planTier: planTier,
      planId: planId,
      hmoId: hmoId,
    );
  }

