  dosagePreviewWidgetContainer({
    required BuildContext context,
    required int callback,
    required Color color,
    required List<int> listOfTimes,
    required List<Map<String, dynamic>> dosageMap,
  }) {
    return Container(
      width: double.infinity,
      margin: EdgeInsets.only(bottom: 10.w),
      padding: EdgeInsets.symmetric(
        vertical: dosageAfterValue == callback ? 12.w : 8.w,
        horizontal: 14.w,
      ),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: color, width: 2),
        color: AppColors.white,
      ),
      child: dosageAfterValue == callback
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // 🔹 Render each day
                ...dosageMap.asMap().entries.map((entry) {
                  final v = entry.value; // {day: 1, doses: [...]}

                  return Padding(
                    padding: EdgeInsets.only(bottom: 14.h),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        // 🔹 Day header
                        Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            TextView(
                              text: "Day ${v['day']}",
                              textStyle: TextStyle(
                                fontFamily: 'GoogleSans',
                                fontSize: 15.20.sp,
                                fontWeight: FontWeight.w600,
                                color: AppColors.black,
                              ),
                            ),
                            IconButton(
                              onPressed: () {
                                dosageAfterValue = null;
                                locator<AuthViewModel>().notifyListeners();
                              },
                              icon: Icon(
                                Icons.keyboard_arrow_down,
                                color: AppColors.grey1,
                                size: 24.sp,
                              ),
                            ),
                          ],
                        ),
                        SizedBox(height: 8.h),

                        // 🔹 Loop through doses of this day
                        ...List.generate((v['doses'] as List).length, (j) {
                          final dose = v['doses'][j];
                          final isLast = j == (v['doses'] as List).length - 1;
                          return Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              SizedBox(height: 4.h),
                              TextView(
                                text: "Dose ${j + 1}",
                                textStyle: TextStyle(
                                  fontFamily: 'Arial',
                                  fontSize: 14.20.sp,
                                  fontWeight: FontWeight.w400,
                                  color: AppColors.infoGrey,
                                ),
                              ),
                              SizedBox(height: 4.h),
                              TextView(
                                text: "${dose['time']}",
                                textStyle: TextStyle(
                                  fontFamily: 'Arial',
                                  fontSize: 16.20.sp,
                                  fontWeight: FontWeight.w400,
                                ),
                              ),
                              SizedBox(height: 6.10.h),
                              if (!isLast)
                                Divider(
                                  color: AppColors.fineGrey,
                                  thickness: .4,
                                ),
                              if (!isLast) SizedBox(height: 6.10.h),
                            ],
                          );
                        }),
                      ],
                    ),
                  );
                }),
              ],
            )
          : Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                TextView(
                  text: 'Day ${callback + 1}',
                  textStyle: TextStyle(
                    fontFamily: 'GoogleSans',
                    fontSize: 15.20.sp,
                    color: AppColors.black,
                    fontWeight: FontWeight.w500,
                  ),
                ),
                IconButton(
                  onPressed: () {
                    dosageAfterValue = callback;
                    locator<AuthViewModel>().notifyListeners();
                  },
                  icon: Icon(
                    Icons.keyboard_arrow_down,
                    color: AppColors.grey1,
                    size: 24.sp,
                  ),
                ),
              ],
            ),
    );
  }

