  Future<void> _calculateEndDate({
    StateSetter? setModalState,
    AuthViewModel? model,
  }) async {
    if (model!.pickedDatedStart != null &&
        model.medDurationController.text.isNotEmpty) {
      final days = int.tryParse(model.medDurationController.text) ?? 0;

      // ✅ Calculate directly
      final endDate = model.pickedDatedStart!.add(Duration(days: days - 1));

      // ✅ Store DateTime (recommended)
      model.pickedEndDate = endDate.toString();

      // ✅ Format ONLY for UI
      model.endDateController.text = DateFormat('dd MMM, yyyy').format(endDate);

      // ✅ Convert to ISO (no need for parse again)
      model.endDateIso = DateTime.utc(
        endDate.year,
        endDate.month,
        endDate.day,
      ).toIso8601String();

      model.returnNoDays = days;

      await Future.delayed(const Duration(seconds: 1));

      model.intListCustom = List.generate(
        model.returnNoDays!,
        (index) => index,
      );

      setModalState?.call(() {});
      notifyListeners();
    }
  }

  Future<void> _calculateEndDateEdit({
    StateSetter? setModalState,
    AuthViewModel? model,
    getReminderId.Data? data,
  }) async {
    if (data!.medication!.durationInDays != null) {
      final days = data.medication!.durationInDays ?? 0;

      // ✅ Calculate directly
      final endDate = data.medication!.startDateTime!.add(
        Duration(days: days - 1),
      );

      // ✅ Store DateTime (recommended)
      model!.pickedEndDate = endDate.toString();

      // ✅ Format ONLY for UI;
      data.medication!.endDateTime = endDate;

      // ✅ Convert to ISO (no need for parse again)
      model.endDateIso = DateTime.utc(
        endDate.year,
        endDate.month,
        endDate.day,
      ).toIso8601String();

      model.returnNoDays = days;

      await Future.delayed(const Duration(seconds: 1));

      model.intListCustom = List.generate(
        model.returnNoDays!,
        (index) => index,
      );

      setModalState?.call(() {});
      model.notifyListeners();
    }
  }

