      model!.pickedEndDate = endDate.toString();

      // ✅ Format ONLY for UI;
      data.medication!.endDateTime = endDate;

      // ✅ Convert to ISO (no need for parse again)
      model.endDateIso = DateTime.utc(
        endDate.year,
        endDate.month,
        endDate.day,
      ).toIso8601String();

      model.returnNoDays = days;

      await Future.delayed(const Duration(seconds: 1));

      model.intListCustom = List.generate(
        model.returnNoDays!,
        (index) => index,
      );

      setModalState?.call(() {});
      model.notifyListeners();
    }
  }

  Future<void> _calculateEndDateEditDraft({
    StateSetter? setModalState,
    AuthViewModel? model,
    draftPay.Medication? data,
  }) async {
    if (data!.durationInDays != null) {
      final days = data.durationInDays ?? 0;

      // ✅ Calculate directly
      final endDate = data.startDateTime!.add(Duration(days: days - 1));

      // ✅ Store DateTime (recommended)
      model!.pickedEndDate = endDate.toString();

      // ✅ Format ONLY for UI;
      data.endDateTime = endDate;

      // ✅ Convert to ISO (no need for parse again)
      model.endDateIso = DateTime.utc(
        endDate.year,
        endDate.month,
        endDate.day,
      ).toIso8601String();

      model.returnNoDays = days;

      await Future.delayed(const Duration(seconds: 1));

      model.intListCustom = List.generate(
        model.returnNoDays!,
        (index) => index,
      );

      setModalState?.call(() {});
      model.notifyListeners();
    }
  }

  Future<void> _calculateEndDateUpdate({
    StateSetter? setModalState,
    AuthViewModel? model,
    int? index,
  }) async {
    if (model!.startDateUpdateControllers[index!].text.isNotEmpty &&
        model.durationUpdateControllers[index].text.isNotEmpty) {
      final days =
          int.tryParse(model.durationUpdateControllers[index].text) ?? 0;

      // ✅ FIXED parsing
      final startDate = DateFormat(
        'dd MMM, yyyy',
      ).parse(model.startDateUpdateControllers[index].text);

      final endDate = startDate.add(Duration(days: days - 1));

      // ✅ Format for UI
      model.endDateUpdateController[index].text = DateFormat(
        'dd MMM, yyyy',
      ).format(endDate);

      // ✅ ISO
      model.endDateIso = DateTime.utc(
        endDate.year,
        endDate.month,
        endDate.day,
      ).toIso8601String();

      // model.returnNoDays = days;
      model.medicationClassList[index].duration = days.toString();

      model.numberOfDurationsInDaysList![index] = getReturnDurationNumberOfDays(
        days,
      );

      await Future.delayed(const Duration(seconds: 1));

      model.intListCustom = List.generate(days, (i) => i);

      setModalState?.call(() {});
      notifyListeners();
    }
  }

