  void addTimeForDay(int day, StateSetter setModalState) {
    final time = selectedTimePerDay[day];

    if (time == null) return;

    if (timesPerDay[day]!.length >= 100) {
      return;
    }

    if (!timesPerDay[day]!.contains(time)) {
      timesPerDay[day]!.add(time);
    }

    setModalState(() {});
    notifyListeners();
  }

  void addTimeForDayUpdate({
    StateSetter? setModalState,
    List<dose.DailyDoseTime>? dailyDoseTimes,
    String? time,
    String? date,
  }) {
    if (dailyDoseTimes == null) return;

    if (dailyDoseTimes.length >= 100) {
      return;
    }
    final parsedDate = DateTime.parse(date!);

    dailyDoseTimes.add(
      dose.DailyDoseTime(
        time: time,
        date: date,
        isoDate: DateTime.utc(
          parsedDate.year,
          parsedDate.month,
          parsedDate.day,
        ).toUtc(),
        status: "PENDING",
      ),
    );
    setModalState!(() {});
    notifyListeners();
  }

