  Future<void> getActualTimeOfTheDay() async {
    final hour = DateTime.now().hour;

    if (hour < 12) {
      timePeriod = 'morning';
    } else if (hour < 17) {
      timePeriod = 'afternoon';
    } else if (hour < 21) {
      timePeriod = 'evening';
    }
    notifyListeners();
  }

