  onAddAllLoading() async {
    pageAll++;
    onLoading(pageAll);
    notifyListeners();
  }

  onAddGoingLoading() async {
    pageOngoing++;
    onLoading(pageOngoing);
    notifyListeners();
  }

  onAddCompletedLoading() async {
    pageCompleted++;
    onLoading(pageCompleted);
    notifyListeners();
  }

  onAddTodayLoading() async {
    pageToday++;
    onLoading(pageToday);
    notifyListeners();
  }

  onSubAllLoading() async {
    pageAll--;
    onLoading(pageAll);
    notifyListeners();
  }

  onSubGoingLoading() async {
    pageOngoing--;
    onLoading(pageOngoing);
    notifyListeners();
  }

  onSubCompletedLoading() async {
    pageCompleted--;
    onLoading(pageCompleted);
    notifyListeners();
  }

  onSubTodayLoading() async {
    pageToday--;
    onLoading(pageToday);
    notifyListeners();
  }

  Future<void> onLoading(page) async {
    await Future.delayed(const Duration(milliseconds: 100));

    if (_getReminderResponseModel!.data!.reminders!.isNotEmpty) {
      try {
        _isLoading = true;
        if (isReminderStatus == 'all' ||
            isReminderStatus == '' ||
            isReminderStatus == null) {
          _getReminderResponseModel = await runBusyFuture(
            repositoryImply.getReminderAll(
              page: page.toString(),
              limit: 10.toString(),
            ),
            throwException: true,
          );
        } else {
          _getReminderResponseModel = await runBusyFuture(
            repositoryImply.getReminder(
              status: isReminderStatus,
              page: page.toString(),
              limit: 10.toString(),
            ),
            throwException: true,
          );
        }
        _isLoading = false;
      } catch (e) {
        _isLoading = false;
        rethrow;
      }
    } else {
      isLoadNoMore = true;
      null;
    }
    _isLoading = false;
    notifyListeners();
  }

