  Future<void> _pickCsvFile({
    BuildContext? context,
    String? docType,
    String? planType,
    String? planTier,
    int? index,
  }) async {
    // 1. Pick the file
    FilePickerResult? result = await FilePicker.platform.pickFiles(
      type: FileType.custom,
      allowedExtensions: ['csv'],
      allowMultiple: false,
    );

    if (result != null) {
      // 2. Get the file path
      String path = result.files.first.path!;
      _filePath = path;
      notifyListeners();

      // 3. Read and parse the file
      await _parseCsv(
        path: path,
        docType: docType,
        planType: planType,
        planTier: planTier,
        index: index,
      );
    } else {
      // User canceled the picker
    }
  }

  Future<void> _parseCsv({
    String? path,
    String? docType,
    String? planType,
    String? planTier,
    int? index,
  }) async {
    try {
      final input = File(path!).openRead();
      final fields = await input
          .transform(utf8.decoder)
          .transform(csv.decoder)
          .toList();
      _csvData = fields;
      imageDocument = File(path);
      fileImageDocument = imageDocument!.path.split("/").last;
      _isLoadingDoc1 = true;
      await uploadDocument(
        context: context,
        applicationId: session.applicationGlobalId['$planType:$planTier'],
        file: MultipartFile.fromBytes(
          formartFileImage(imageDocument).readAsBytesSync(),
          filename: imageDocument!.path.split("/").last,
        ),
        index: index,
        docType: docType,
      );
      _isLoadingDoc1 = false;
      // logger.d('CSV Data: $_csvData');
      logger.d('input .CSV File Data: $input');
      notifyListeners();
    } catch (e) {
      // print("Error parsing CSV: $e");
    }
  }

  fileTextListLength(int? length) {
