  void getMySubscriptionDetails(
    context, {
    String page = '1',
    String limit = '10',
    String? subStatus,
    String? appStatus,
  }) async {
    try {
      _isLoading = true;
      _getMySubscriptionResponseModel = await runBusyFuture(
        repositoryImply.getMySubscriptions(
          page: page,
          limit: limit,
          subStatus: subStatus,
          appStatus: appStatus,
        ),
        throwException: true,
      );
      _isLoading = false;
      mySubscriptionIndexIncrement = 1;
      mySubscriptionIndex = 0;
    } catch (e) {
      _isLoading = false;
      logger.d(e);
      // AppUtils.snackbar(context, message: e.toString(), error: true);
    }
    notifyListeners();
  }

